#include <iostream>

int gcd(int a, int b)
{
    while (b != 0)
    {
        int r{ a % b };
        a = b;
        b = r;
    }

    return a;
}

long long lcm(int a, int b)
{
    return static_cast<long long>(a / gcd(a, b)) * b;
}

int main()
{
    int a{};
    int b{};
    if (!(std::cin >> a >> b)) return 0;

    std::cout << "gcd " << gcd(a, b) << "\n";
    std::cout << "lcm " << lcm(a, b) << "\n";

    return 0;
}
